"""Scheduling engine: run state machine, leases, retries, history, replay.

All state transitions funnel through :class:`Scheduler` so the append-only
history stays the single source of truth.  ``replay`` rebuilds current state
from that history and must agree with the stored document.
"""

import math
import time as _time

from .model import KIND_APPROVAL, WorkflowError, format_time
from .store import (
    RUN_FAILED,
    RUN_PENDING,
    RUN_RUNNING,
    RUN_SUCCEEDED,
    STEP_FAILED,
    STEP_PENDING,
    STEP_READY,
    STEP_RUNNING,
    STEP_SUCCEEDED,
    STEP_WAITING,
    WorkflowStore,
    new_run,
)


class LeaseError(WorkflowError):
    """Raised when a worker does not hold the lease it is acting on."""

    def __init__(self, message, code="lease_not_held"):
        super().__init__(message, code)


class ConflictError(WorkflowError):
    """Raised for an action that is incompatible with the step's state."""

    def __init__(self, message, code="conflict"):
        super().__init__(message, code)


def backoff_seconds(attempt, base=1.0):
    """Exponential backoff: ``base * 2 ** (attempt - 1)``."""
    return float(base) * (2 ** (max(1, int(attempt)) - 1))


def _promote_pending(run, now_iso):
    """Promote pending steps whose dependencies all succeeded.

    Ordinary tasks become ``ready``; approval steps become ``waiting`` for a
    human decision.  Returns ``(ready_ids, waiting_ids)``.
    """
    index = run["order_index"]
    ready, waiting = [], []
    for sid in sorted(run["steps"], key=lambda s: index.get(s, 0)):
        step = run["steps"][sid]
        if step["status"] != STEP_PENDING:
            continue
        if all(run["steps"][d]["status"] == STEP_SUCCEEDED for d in step["depends_on"]):
            if step.get("kind") == KIND_APPROVAL:
                step["status"] = STEP_WAITING
                waiting.append(sid)
            else:
                step["status"], step["ready_at"] = STEP_READY, now_iso
                ready.append(sid)
    return ready, waiting


def _derive_run_status(run):
    """Derive the run status from its steps; stays ``pending`` until claimed."""
    steps = list(run["steps"].values())
    if any(s["status"] == STEP_FAILED for s in steps):
        return RUN_FAILED
    if steps and all(s["status"] == STEP_SUCCEEDED for s in steps):
        return RUN_SUCCEEDED
    if any(s["status"] in (STEP_RUNNING, STEP_SUCCEEDED) for s in steps):
        return RUN_RUNNING
    return RUN_PENDING


class Scheduler:
    """Coordinates workers against a :class:`WorkflowStore`."""

    def __init__(self, store, clock=None, backoff_base=1.0, sleep=None):
        self.store = store
        self._clock = clock if clock is not None else store.now
        self.backoff_base = float(backoff_base)
        self._sleep = sleep if sleep is not None else _time.sleep

    def now(self):
        return float(self._clock())

    def _iso(self, when=None):
        return format_time(self.now() if when is None else when)

    def _event(self, run, run_id, step_id, etype, attempt=None, worker_id=None, **extra):
        event = {"at": self._iso(), "run_id": run_id, "step_id": step_id, "type": etype,
                 "attempt": attempt, "worker_id": worker_id}
        event.update(extra)
        run["history"].append(event)
        return event

    # -- workflow / run lifecycle --------------------------------------
    def submit(self, tenant, workflow_id, steps):
        return self.store.save_workflow(tenant, workflow_id, steps)

    def start_run(self, tenant, workflow_id, run_id=None, params=None):
        plan = self.store.get_workflow(tenant, workflow_id)
        with self.store.locked():
            run_id = run_id or self.store.generate_run_id()
            if self.store.run_exists(run_id) == tenant:
                raise WorkflowError("run already exists: %s" % run_id, "duplicate_run")
            run = new_run(tenant, workflow_id, run_id, params, plan, self._iso())
            self._event(run, run_id, None, "run_created")
            ready, waiting = _promote_pending(run, self._iso())
            for sid in ready:
                self._event(run, run_id, sid, "ready", attempt=0)
            for sid in waiting:
                self._event(run, run_id, sid, "waiting", attempt=0)
            run["status"], run["updated_at"] = _derive_run_status(run), self._iso()
            return self.store.save_run(run)

    def get_run(self, tenant, run_id):
        run = self.store.load_run(tenant, run_id)
        if run["tenant"] != tenant:
            raise WorkflowError("run %s belongs to another tenant" % run_id, "cross_tenant")
        return run

    def list_runs(self, tenant, status=None, limit=50, after=None):
        return self.store.list_runs(tenant, status=status, limit=limit, after=after)

    def history(self, run_id, tenant=None):
        if tenant is None:
            tenant = self.store.run_exists(run_id)
            if tenant is None:
                raise WorkflowError("unknown run: %s" % run_id, "unknown_run")
        return list(self.get_run(tenant, run_id)["history"])

    # -- lease expiry --------------------------------------------------
    def _expire_leases(self, run, now):
        """Release leases past their deadline; each one records a takeover."""
        reclaimed = []
        for sid in sorted(run["steps"], key=lambda s: run["order_index"].get(s, 0)):
            step = run["steps"][sid]
            if step["status"] != STEP_RUNNING:
                continue
            if step.get("lease_deadline") is None or float(step["lease_deadline"]) > now:
                continue
            holder = step["worker_id"]
            step.update(status=STEP_READY, worker_id=None, lease_deadline=None, ready_at=self._iso())
            self._event(run, run["run_id"], sid, "takeover", attempt=step["attempt"], worker_id=holder)
            reclaimed.append(sid)
        return reclaimed

    # -- claim / complete / fail ---------------------------------------
    def claim(self, tenant, run_id, worker_id, lease_seconds=30):
        """Lease the next ready step, or return ``None`` when none is ready."""
        if not isinstance(worker_id, str) or not worker_id.strip():
            raise WorkflowError("worker_id must be a non-empty string", "bad_worker")
        if not isinstance(lease_seconds, (int, float)) or isinstance(lease_seconds, bool) \
                or lease_seconds <= 0:
            raise WorkflowError("lease_seconds must be a positive number", "bad_lease")
        now = self.now()
        with self.store.locked():
            run = self.get_run(tenant, run_id)
            self._expire_leases(run, now)
            ready, waiting = _promote_pending(run, self._iso())
            for sid in ready:
                self._event(run, run_id, sid, "ready", attempt=run["steps"][sid]["attempt"])
            for sid in waiting:
                self._event(run, run_id, sid, "waiting", attempt=0)
            candidates = [s for s in run["steps"].values() if s["status"] == STEP_READY]
            index = run["order_index"]
            step = min(candidates, key=lambda s: (index.get(s["id"], 0), s["id"])) if candidates else None
            previous = run["status"]
            if step is not None:
                step.update(status=STEP_RUNNING, worker_id=worker_id, next_attempt_at=None,
                            lease_deadline=now + float(lease_seconds), started_at=self._iso())
                self._event(run, run_id, step["id"], "claim", attempt=step["attempt"],
                            worker_id=worker_id, lease_deadline=step["lease_deadline"])
            run["status"] = _derive_run_status(run)
            if step is not None and run["status"] == RUN_RUNNING and previous == RUN_PENDING:
                self._event(run, run_id, None, "run_started")
            run["updated_at"] = self._iso()
            self.store.save_run(run)
            return dict(step) if step is not None else None

    def heartbeat(self, tenant, run_id, step_id, worker_id, lease_seconds=30):
        """Renew the lease on a running step held by ``worker_id``.

        The new deadline is the later of the current one and
        ``now + lease_seconds``; only the deadline and ``updated_at`` change.
        A renewal that would not extend the deadline returns the run
        unchanged and appends no history.
        """
        if not isinstance(worker_id, str) or not worker_id.strip():
            raise WorkflowError("worker_id must be a non-empty string", "bad_worker")
        if not isinstance(step_id, str) or not step_id.strip():
            raise WorkflowError("step_id must be a non-empty string", "bad_step")
        if not isinstance(lease_seconds, (int, float)) or isinstance(lease_seconds, bool) \
                or not math.isfinite(lease_seconds) or lease_seconds <= 0:
            raise WorkflowError("lease_seconds must be a positive number", "bad_lease")
        now = self.now()
        with self.store.locked():
            owner = self.store.run_exists(run_id)
            if owner is not None and owner != tenant:
                raise WorkflowError("run %s belongs to another tenant" % run_id, "cross_tenant")
            run = self.get_run(tenant, run_id)
            if run["status"] in (RUN_SUCCEEDED, RUN_FAILED):
                raise ConflictError("run %s is already %s" % (run_id, run["status"]),
                                    "run_finished")
            step = run["steps"].get(step_id)
            if step is None:
                raise WorkflowError("unknown step: %s" % step_id, "unknown_step")
            if step.get("kind") == KIND_APPROVAL:
                raise ConflictError(
                    "step %s is an approval node; use /decision" % step_id, "not_a_task"
                )
            if step["status"] != STEP_RUNNING:
                raise LeaseError("step %s is not running" % step_id, "lease_not_held")
            if step["worker_id"] != worker_id:
                raise LeaseError("step %s lease is not held by worker %s" % (step_id, worker_id))
            deadline = float(step["lease_deadline"])
            if now >= deadline:
                raise LeaseError("lease for step %s expired" % step_id, "lease_expired")
            new_deadline = max(deadline, now + float(lease_seconds))
            if new_deadline <= deadline:
                return run
            step["lease_deadline"] = new_deadline
            self._event(run, run_id, step_id, "heartbeat", attempt=step["attempt"],
                        worker_id=worker_id, lease_deadline=new_deadline)
            run["updated_at"] = self._iso()
            self.store.save_run(run)
            return run

    def _require_lease(self, run, step_id, worker_id):
        step = run["steps"].get(step_id)
        if step is None:
            raise WorkflowError("unknown step: %s" % step_id, "unknown_step")
        if step["status"] == STEP_RUNNING and step["worker_id"] == worker_id:
            return step
        raise LeaseError("step %s lease is not held by worker %s" % (step_id, worker_id))

    def complete(self, tenant, run_id, step_id, worker_id, result=None):
        """Idempotent: repeating the same complete is a no-op."""
        now = self.now()
        with self.store.locked():
            run = self.get_run(tenant, run_id)
            step = run["steps"].get(step_id)
            if step is None:
                raise WorkflowError("unknown step: %s" % step_id, "unknown_step")
            if step.get("kind") == KIND_APPROVAL:
                raise ConflictError(
                    "step %s is an approval node; use /decision" % step_id, "not_a_task"
                )
            if step["status"] == STEP_SUCCEEDED and step["worker_id"] == worker_id:
                return run
            step = self._require_lease(run, step_id, worker_id)
            if float(step["lease_deadline"]) <= now:
                raise LeaseError("lease for step %s expired" % step_id, "lease_expired")
            step.update(attempt=step["attempt"] + 1, status=STEP_SUCCEEDED, result=result,
                        error=None, finished_at=self._iso(), lease_deadline=None)
            self._event(run, run_id, step_id, "complete", attempt=step["attempt"],
                        worker_id=worker_id, result=result)
            ready, waiting = _promote_pending(run, self._iso())
            for sid in ready:
                self._event(run, run_id, sid, "ready", attempt=run["steps"][sid]["attempt"])
            for sid in waiting:
                self._event(run, run_id, sid, "waiting", attempt=0)
            run["status"] = _derive_run_status(run)
            if run["status"] == RUN_SUCCEEDED:
                self._event(run, run_id, None, "run_succeeded")
            run["updated_at"] = self._iso()
            self.store.save_run(run)
            return run

    def fail(self, tenant, run_id, step_id, worker_id, error=None):
        """Count the attempt, retry with backoff, or fail the step and run."""
        now = self.now()
        with self.store.locked():
            run = self.get_run(tenant, run_id)
            step = run["steps"].get(step_id)
            if step is None:
                raise WorkflowError("unknown step: %s" % step_id, "unknown_step")
            if step.get("kind") == KIND_APPROVAL:
                raise ConflictError(
                    "step %s is an approval node; use /decision" % step_id, "not_a_task"
                )
            step = self._require_lease(run, step_id, worker_id)
            step.update(attempt=step["attempt"] + 1, worker_id=None, lease_deadline=None, error=error)
            self._event(run, run_id, step_id, "fail", attempt=step["attempt"], worker_id=worker_id,
                        error=error)
            if step["attempt"] >= int(step["max_attempts"]):
                step.update(status=STEP_FAILED, finished_at=self._iso(), next_attempt_at=None)
                self._event(run, run_id, step_id, "attempts_exhausted", attempt=step["attempt"],
                            worker_id=worker_id)
            else:
                step.update(status=STEP_READY, ready_at=self._iso(),
                            next_attempt_at=self._iso(now + backoff_seconds(
                                step["attempt"], self.backoff_base)))
                self._event(run, run_id, step_id, "retry", attempt=step["attempt"],
                            worker_id=worker_id)
            run["status"] = _derive_run_status(run)
            if run["status"] == RUN_FAILED:
                self._event(run, run_id, None, "run_failed")
            run["updated_at"] = self._iso()
            self.store.save_run(run)
            return run

    # -- human decisions -----------------------------------------------
    def decide(self, tenant, run_id, step_id, actor, decision):
        """Record a human approve/reject decision for an approval step.

        Repeating the *same* decision from the *same* actor is idempotent and
        returns the unchanged run; a different actor or the opposite decision
        conflicts with the recorded decision.
        """
        if not isinstance(actor, str) or not actor.strip():
            raise WorkflowError("actor must be a non-empty string", "bad_actor")
        actor = actor.strip()
        if decision not in ("approve", "reject"):
            raise WorkflowError("decision must be 'approve' or 'reject'", "bad_decision")
        with self.store.locked():
            run = self.get_run(tenant, run_id)
            step = run["steps"].get(step_id)
            if step is None:
                raise WorkflowError("unknown step: %s" % step_id, "unknown_step")
            if step.get("kind") != KIND_APPROVAL:
                raise ConflictError("step %s is not an approval node" % step_id, "not_an_approval")
            recorded = step.get("approval")
            if recorded is not None:
                if recorded["actor"] == actor and recorded["decision"] == decision:
                    return run
                raise ConflictError(
                    "step %s already decided by %s: %s"
                    % (step_id, recorded["actor"], recorded["decision"]),
                    "already_decided",
                )
            if step["status"] != STEP_WAITING:
                raise ConflictError(
                    "step %s is not waiting for a decision" % step_id, "not_waiting"
                )
            event = self._event(run, run_id, step_id, "decision", attempt=0, worker_id=None,
                                actor=actor, decision=decision)
            at = event["at"]
            step["approval"] = {"actor": actor, "decision": decision, "at": at}
            previous = run["status"]
            if decision == "approve":
                step.update(status=STEP_SUCCEEDED, finished_at=at)
                ready, waiting = _promote_pending(run, at)
                for sid in ready:
                    self._event(run, run_id, sid, "ready", attempt=run["steps"][sid]["attempt"])
                for sid in waiting:
                    self._event(run, run_id, sid, "waiting", attempt=0)
                run["status"] = _derive_run_status(run)
            else:
                step.update(status=STEP_FAILED, finished_at=at)
                run["status"] = RUN_FAILED
            if run["status"] == RUN_RUNNING and previous == RUN_PENDING:
                self._event(run, run_id, None, "run_started")
            if run["status"] == RUN_SUCCEEDED:
                self._event(run, run_id, None, "run_succeeded")
            elif run["status"] == RUN_FAILED:
                self._event(run, run_id, None, "run_failed")
            run["updated_at"] = at
            self.store.save_run(run)
            return run

    # -- history / replay ----------------------------------------------
    def replay(self, tenant, run_id):
        """Rebuild run state from the append-only history."""
        stored = self.get_run(tenant, run_id)
        plan = self.store.get_workflow(tenant, stored["workflow_id"])
        rebuilt = new_run(tenant, stored["workflow_id"], run_id, stored.get("params"), plan,
                          stored["created_at"])
        steps = rebuilt["steps"]
        for event in stored["history"]:
            sid, etype, at = event.get("step_id"), event.get("type"), event.get("at")
            attempt = event.get("attempt")
            if sid is None:
                if etype == "run_succeeded":
                    rebuilt["status"] = RUN_SUCCEEDED
                elif etype == "run_failed":
                    rebuilt["status"] = RUN_FAILED
                elif etype == "run_started" and rebuilt["status"] == RUN_PENDING:
                    rebuilt["status"] = RUN_RUNNING
                continue
            step = steps.get(sid)
            if step is None:
                continue
            if etype == "ready":
                step.update(status=STEP_READY, ready_at=at)
            elif etype == "waiting":
                step.update(status=STEP_WAITING)
            elif etype == "claim":
                step.update(status=STEP_RUNNING, worker_id=event.get("worker_id"),
                            started_at=at, lease_deadline=event.get("lease_deadline"))
            elif etype == "heartbeat":
                step["lease_deadline"] = event.get("lease_deadline")
            elif etype == "takeover":
                step.update(status=STEP_READY, worker_id=None, lease_deadline=None)
            elif etype == "complete":
                step.update(status=STEP_SUCCEEDED, result=event.get("result"), finished_at=at,
                            lease_deadline=None, worker_id=None,
                            attempt=step["attempt"] if attempt is None else attempt)
            elif etype == "decision":
                step.update(status=STEP_SUCCEEDED if event.get("decision") == "approve"
                            else STEP_FAILED, finished_at=at,
                            approval={"actor": event.get("actor"),
                                      "decision": event.get("decision"), "at": at})
            elif etype == "fail":
                step.update(error=event.get("error"), worker_id=None, lease_deadline=None,
                            attempt=step["attempt"] if attempt is None else attempt)
            elif etype == "retry":
                step["status"] = STEP_READY
            elif etype == "attempts_exhausted":
                step.update(status=STEP_FAILED, finished_at=at)
        if all(s["status"] == STEP_SUCCEEDED for s in steps.values()):
            rebuilt["status"] = RUN_SUCCEEDED
        elif any(s["status"] == STEP_FAILED for s in steps.values()):
            rebuilt["status"] = RUN_FAILED
        return rebuilt

"""DAG definition, validation and shared helpers for flowd.

A workflow is a named DAG of steps; every step is a mapping::

    {"id": "build", "depends_on": ["fetch"], "max_attempts": 3}

Validation rejects duplicate ids, empty ids, unknown dependencies,
self/cyclic dependencies and bad ``max_attempts`` values.  A validated plan
is returned topologically sorted (ties broken by step id) so scheduling
order is deterministic.
"""

import heapq
import time as _time

STEP_STATES = ("pending", "ready", "running", "waiting", "succeeded", "failed")
RUN_STATES = ("pending", "running", "succeeded", "failed")
DEFAULT_MAX_ATTEMPTS = 3

KIND_TASK = "task"
KIND_APPROVAL = "approval"
STEP_KINDS = (KIND_TASK, KIND_APPROVAL)


class WorkflowError(Exception):
    """Raised for any rejected workflow definition or illegal call."""

    def __init__(self, message, code="invalid_workflow"):
        super().__init__(message)
        self.code = code
        self.message = message


def format_time(seconds):
    """Render epoch ``seconds`` as a sortable UTC ISO-8601 timestamp."""
    whole = int(seconds)
    micros = int(round((seconds - whole) * 1000000))
    if micros >= 1000000:
        whole, micros = whole + 1, micros - 1000000
    return "%s.%06dZ" % (_time.strftime("%Y-%m-%dT%H:%M:%S", _time.gmtime(whole)), micros)


def validate_step(raw, index, seen_ids):
    """Validate one step definition and return its normalized form."""
    if not isinstance(raw, dict):
        raise WorkflowError("step %d must be an object" % index)
    step_id = raw.get("id")
    if not isinstance(step_id, str):
        raise WorkflowError("step %d is missing a string id" % index)
    step_id = step_id.strip()
    if not step_id:
        raise WorkflowError("step %d has an empty id" % index)
    if step_id in seen_ids:
        raise WorkflowError("duplicate step id: %s" % step_id, "duplicate_step")
    seen_ids.add(step_id)
    depends_on = raw.get("depends_on") or []
    if not isinstance(depends_on, list):
        raise WorkflowError("step %s: depends_on must be a list" % step_id)
    for dep in depends_on:
        if not isinstance(dep, str) or not dep.strip():
            raise WorkflowError("step %s: depends_on entries must be non-empty strings" % step_id)
    depends_on = [d.strip() for d in depends_on]
    if len(set(depends_on)) != len(depends_on):
        raise WorkflowError("step %s: duplicate dependencies" % step_id)
    if step_id in depends_on:
        raise WorkflowError("step %s depends on itself" % step_id, "self_dependency")
    max_attempts = raw.get("max_attempts")
    if max_attempts is None:
        max_attempts = DEFAULT_MAX_ATTEMPTS
    if isinstance(max_attempts, bool) or not isinstance(max_attempts, int):
        raise WorkflowError("step %s: max_attempts must be an integer" % step_id, "bad_max_attempts")
    if max_attempts < 1:
        raise WorkflowError("step %s: max_attempts must be >= 1" % step_id, "bad_max_attempts")
    kind = raw.get("kind")
    if kind is None:
        kind = KIND_TASK
    if not isinstance(kind, str) or kind not in STEP_KINDS:
        raise WorkflowError(
            "step %s: kind must be one of %s" % (step_id, ", ".join(STEP_KINDS)), "bad_kind"
        )
    return {"id": step_id, "depends_on": depends_on, "max_attempts": max_attempts, "kind": kind}


def topo_order(steps):
    """Return step ids in dependency order using Kahn's algorithm."""
    ids = [s["id"] for s in steps]
    children = {sid: [] for sid in ids}
    indegree = {}
    for step in steps:
        for dep in step["depends_on"]:
            children[dep].append(step["id"])
        indegree[step["id"]] = len(step["depends_on"])
    heap = [(sid, sid) for sid in ids if indegree[sid] == 0]
    heapq.heapify(heap)
    order = []
    while heap:
        _, sid = heapq.heappop(heap)
        order.append(sid)
        for child in sorted(children[sid]):
            indegree[child] -= 1
            if indegree[child] == 0:
                heapq.heappush(heap, (child, child))
    if len(order) != len(ids):
        raise WorkflowError(
            "cyclic dependency involving: %s" % ", ".join(sorted(set(ids) - set(order))), "cycle"
        )
    return order


def plan_workflow(workflow_id, steps):
    """Validate ``steps`` and return a normalized, topologically sorted plan."""
    if not isinstance(workflow_id, str) or not workflow_id.strip():
        raise WorkflowError("workflow_id must be a non-empty string")
    if not isinstance(steps, list) or not steps:
        raise WorkflowError("steps must be a non-empty list")
    seen = set()
    normalized = [validate_step(raw, i, seen) for i, raw in enumerate(steps)]
    for step in normalized:
        for dep in step["depends_on"]:
            if dep not in seen:
                raise WorkflowError(
                    "step %s depends on unknown step: %s" % (step["id"], dep), "unknown_dependency"
                )
    order = topo_order(normalized)
    index = {sid: i for i, sid in enumerate(order)}
    return {
        "workflow_id": workflow_id.strip(),
        "steps": sorted(normalized, key=lambda s: index[s["id"]]),
        "order": order,
    }

"""Persistence for flowd: workflows, runs, tenants and append-only history.

Layout::

    <root>/<tenant>/workflows.json
    <root>/<tenant>/runs/<run_id>.json

Every write is atomic (temp file + ``os.replace``) so a crash cannot leave a
half written run behind, and a fresh store over the same root sees exactly
the same workflows and runs.
"""

import json
import os
import threading
import time as _time
import uuid
from contextlib import contextmanager

from .model import KIND_TASK, WorkflowError, format_time, plan_workflow

RUN_PENDING = "pending"
RUN_RUNNING = "running"
RUN_SUCCEEDED = "succeeded"
RUN_FAILED = "failed"

STEP_PENDING = "pending"
STEP_READY = "ready"
STEP_RUNNING = "running"
STEP_WAITING = "waiting"
STEP_SUCCEEDED = "succeeded"
STEP_FAILED = "failed"

TERMINAL_RUN_STATES = (RUN_SUCCEEDED, RUN_FAILED)


def atomic_write_json(path, payload):
    """Write ``payload`` as JSON to ``path`` atomically."""
    directory = os.path.dirname(path)
    if directory:
        os.makedirs(directory, exist_ok=True)
    tmp = "%s.tmp.%d" % (path, os.getpid())
    with open(tmp, "w", encoding="utf-8") as handle:
        json.dump(payload, handle, ensure_ascii=True, sort_keys=True, indent=2)
        handle.flush()
        os.fsync(handle.fileno())
    os.replace(tmp, path)


def read_json(path, default=None):
    try:
        with open(path, "r", encoding="utf-8") as handle:
            return json.load(handle)
    except FileNotFoundError:
        return default


class WorkflowStore:
    """Filesystem backed store for one data directory (all tenants)."""

    def __init__(self, root, clock=None):
        self.root = os.path.abspath(root)
        self._clock = clock if clock is not None else _time.time
        self._lock = threading.RLock()
        os.makedirs(self.root, exist_ok=True)

    def now(self):
        return float(self._clock())

    def now_iso(self):
        return format_time(self.now())

    @contextmanager
    def locked(self):
        with self._lock:
            yield

    # -- paths ---------------------------------------------------------
    def tenant_dir(self, tenant):
        if not isinstance(tenant, str) or not tenant.strip():
            raise WorkflowError("tenant must be a non-empty string", "bad_tenant")
        return os.path.join(self.root, tenant.strip())

    def workflows_path(self, tenant):
        return os.path.join(self.tenant_dir(tenant), "workflows.json")

    def run_path(self, tenant, run_id):
        return os.path.join(self.tenant_dir(tenant), "runs", "%s.json" % run_id)

    def generate_run_id(self):
        return "run-" + uuid.uuid4().hex[:12]

    # -- workflows -----------------------------------------------------
    def save_workflow(self, tenant, workflow_id, steps):
        plan = plan_workflow(workflow_id, steps)
        with self._lock:
            data = self.load_workflows(tenant)
            data[plan["workflow_id"]] = plan
            atomic_write_json(self.workflows_path(tenant), data)
        return plan

    def load_workflows(self, tenant):
        return read_json(self.workflows_path(tenant), {}) or {}

    def get_workflow(self, tenant, workflow_id):
        plan = self.load_workflows(tenant).get(workflow_id)
        if plan is None:
            raise WorkflowError("unknown workflow: %s" % workflow_id, "unknown_workflow")
        return plan

    # -- runs ----------------------------------------------------------
    def save_run(self, run):
        atomic_write_json(self.run_path(run["tenant"], run["run_id"]), run)
        return run

    def load_run(self, tenant, run_id):
        run = read_json(self.run_path(tenant, run_id), None)
        if run is None:
            raise WorkflowError("unknown run: %s" % run_id, "unknown_run")
        return normalize_run(run)

    def run_exists(self, run_id):
        """Return the tenant owning ``run_id``, or ``None``."""
        for tenant in sorted(os.listdir(self.root)):
            if os.path.isfile(os.path.join(self.root, tenant, "runs", "%s.json" % run_id)):
                return tenant
        return None

    def list_runs(self, tenant, status=None, limit=50, after=None):
        runs_dir = os.path.join(self.tenant_dir(tenant), "runs")
        items = []
        for name in sorted(os.listdir(runs_dir)) if os.path.isdir(runs_dir) else []:
            run = read_json(os.path.join(runs_dir, name), None) if name.endswith(".json") else None
            if run is not None:
                items.append(normalize_run(run))
        items.sort(key=lambda r: (r.get("created_at", ""), r.get("run_id", "")))
        if status:
            items = [r for r in items if r.get("status") == status]
        if after:
            position = [i for i, r in enumerate(items) if r.get("run_id") == after]
            items = items[position[0] + 1:] if position else []
        limit = max(1, int(limit))
        page = items[:limit]
        return page, (page[-1]["run_id"] if len(items) > limit else None)


def normalize_run(run):
    """Backfill fields missing from documents written by older versions.

    Steps without ``kind`` predate approval nodes and are ordinary tasks.
    Mutates and returns ``run``.
    """
    for step in run.get("steps", {}).values():
        step.setdefault("kind", KIND_TASK)
        step.setdefault("approval", None)
    return run


def new_run(tenant, workflow_id, run_id, params, plan, now_iso):
    """Build a fresh run document from a validated plan."""
    steps = {
        step["id"]: {
            "id": step["id"],
            "kind": step.get("kind", KIND_TASK),
            "depends_on": list(step["depends_on"]),
            "max_attempts": step["max_attempts"],
            "status": STEP_PENDING,
            "attempt": 0,
            "worker_id": None,
            "lease_deadline": None,
            "next_attempt_at": None,
            "ready_at": None,
            "started_at": None,
            "finished_at": None,
            "result": None,
            "error": None,
            "approval": None,
        }
        for step in plan["steps"]
    }
    return {
        "tenant": tenant,
        "workflow_id": workflow_id,
        "run_id": run_id,
        "status": RUN_PENDING,
        "params": params or {},
        "created_at": now_iso,
        "updated_at": now_iso,
        "step_order": list(plan["order"]),
        "order_index": {sid: i for i, sid in enumerate(plan["order"])},
        "steps": steps,
        "history": [],
    }

"""Standard library HTTP API for flowd."""

import json
import re
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import parse_qs, urlparse

from .model import WorkflowError
from .scheduler import ConflictError, LeaseError

MAX_BODY = 1 << 20
STATUS_FOR_CODE = {"unknown_run": 404, "unknown_workflow": 404, "unknown_step": 404,
                   "cross_tenant": 403}
DECISIONS = ("approve", "reject")


class _Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"
    server_version = "flowd/0.1"

    def log_message(self, fmt, *args):  # keep the console quiet
        pass

    # -- plumbing ------------------------------------------------------
    def _send(self, code, raw=b""):
        self.send_response(code)
        if code != 204:
            self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(raw)))
        self.end_headers()
        if raw:
            self.wfile.write(raw)

    def _json(self, code, payload):
        self._send(code, json.dumps(payload, ensure_ascii=True, sort_keys=True).encode("utf-8"))

    def _error(self, code, message):
        self._json(code, {"error": message})

    def _body(self):
        length = int(self.headers.get("Content-Length") or 0)
        if length <= 0:
            return {}
        if length > MAX_BODY:
            raise WorkflowError("request body too large", "body_too_large")
        try:
            payload = json.loads(self.rfile.read(length).decode("utf-8"))
        except (ValueError, UnicodeDecodeError):
            raise WorkflowError("request body must be valid JSON", "bad_json")
        if not isinstance(payload, dict):
            raise WorkflowError("request body must be a JSON object", "bad_json")
        return payload

    def _tenant(self, query, body=None):
        tenant = (body or {}).get("tenant") or (query.get("tenant") or [None])[0]
        if not tenant:
            raise WorkflowError("tenant is required", "bad_tenant")
        return tenant
    # -- verbs ---------------------------------------------------------
    def do_GET(self):
        self._dispatch("GET")

    def do_POST(self):
        self._dispatch("POST")

    def _dispatch(self, method):
        parsed = urlparse(self.path)
        path = parsed.path.rstrip("/") or "/"
        try:
            self._route(method, path, parse_qs(parsed.query))
        except LeaseError as exc:
            self._error(409, exc.message)
        except ConflictError as exc:
            self._error(409, exc.message)
        except WorkflowError as exc:
            self._error(STATUS_FOR_CODE.get(exc.code, 400), exc.message)
        except Exception as exc:  # pragma: no cover - defensive
            self._error(500, "internal error: %s" % exc)

    def _route(self, method, path, query):
        body = {}
        if method == "GET":
            if path == "/healthz":
                return self._json(200, {"ok": True})
            if path == "/v1/runs":
                return self._list_runs(query)
        elif method == "POST":
            if path == "/v1/workflows":
                body = self._body()
                tenant = self._tenant({}, body)
                plan = self.scheduler.submit(tenant, body.get("workflow_id"), body.get("steps"))
                return self._json(201, dict(plan, tenant=tenant))
            if path == "/v1/runs":
                body = self._body()
                run = self.scheduler.start_run(self._tenant({}, body), body.get("workflow_id"),
                                               body.get("run_id"), body.get("params"))
                return self._json(201, _run_view(run))
            action = re.fullmatch(r"/v1/runs/([^/]+)/(claim|complete|fail|decision|heartbeat)", path)
            if action:
                if action.group(2) == "decision":
                    return self._decision(action.group(1), self._body())
                if action.group(2) == "heartbeat":
                    return self._heartbeat(action.group(1), self._body())
                return self._step_action(action.group(1), action.group(2), self._body())
        solo = re.fullmatch(r"/v1/runs/([^/]+)", path)
        if method == "GET" and solo:
            return self._get_run(query, solo.group(1))
        return self._error(404, "no route for %s %s" % (method, path))

    # -- handlers ------------------------------------------------------
    def _get_run(self, query, run_id):
        tenant = self._tenant(query)
        owner = self.scheduler.store.run_exists(run_id)
        if owner is not None and owner != tenant:
            raise WorkflowError("run %s belongs to another tenant" % run_id, "cross_tenant")
        return self._json(200, _run_view(self.scheduler.get_run(tenant, run_id)))

    def _list_runs(self, query):
        tenant = self._tenant(query)
        items, next_after = self.scheduler.list_runs(
            tenant,
            status=(query.get("status") or [None])[0],
            limit=int((query.get("limit") or ["50"])[0]),
            after=(query.get("after") or [None])[0],
        )
        return self._json(200, {"tenant": tenant, "items": [_run_view(r) for r in items],
                                "next_after": next_after})

    def _step_action(self, run_id, action, body):
        tenant, worker_id = self._tenant({}, body), body.get("worker_id")
        if action == "claim":
            step = self.scheduler.claim(tenant, run_id, worker_id, body.get("lease_seconds", 30))
            return self._send(204) if step is None else self._json(200, {"step": _step_view(step)})
        if action == "complete":
            run = self.scheduler.complete(tenant, run_id, body.get("step_id"), worker_id,
                                          body.get("result"))
        else:
            run = self.scheduler.fail(tenant, run_id, body.get("step_id"), worker_id,
                                      body.get("error"))
        return self._json(200, _run_view(run))

    def _heartbeat(self, run_id, body):
        """Renew a lease; strict field validation, anything bad is a 400."""
        for name in ("tenant", "step_id", "worker_id"):
            value = body.get(name)
            if not isinstance(value, str) or not value.strip():
                raise WorkflowError("%s must be a non-empty string" % name, "bad_%s" % name)
        run = self.scheduler.heartbeat(body["tenant"], run_id, body["step_id"],
                                       body["worker_id"], body.get("lease_seconds", 30))
        return self._json(200, _run_view(run))

    def _decision(self, run_id, body):
        """Validate strictly; any missing/blank/wrong-type field is a 400."""
        fields = {}
        for name in ("tenant", "step_id", "actor"):
            value = body.get(name)
            if not isinstance(value, str) or not value.strip():
                raise WorkflowError("%s must be a non-empty string" % name, "bad_%s" % name)
            fields[name] = value.strip()
        decision = body.get("decision")
        if decision not in DECISIONS:
            raise WorkflowError("decision must be one of %s" % ", ".join(DECISIONS),
                                "bad_decision")
        tenant = fields["tenant"]
        owner = self.scheduler.store.run_exists(run_id)
        if owner is not None and owner != tenant:
            raise WorkflowError("run %s belongs to another tenant" % run_id, "cross_tenant")
        run = self.scheduler.decide(tenant, run_id, fields["step_id"], fields["actor"], decision)
        return self._json(200, _run_view(run))


def _step_view(step):
    return {"id": step["id"], "kind": step.get("kind", "task"), "status": step["status"],
            "attempt": step["attempt"],
            "max_attempts": step["max_attempts"], "depends_on": list(step["depends_on"]),
            "worker_id": step["worker_id"], "lease_deadline": step["lease_deadline"],
            "next_attempt_at": step["next_attempt_at"], "result": step.get("result"),
            "error": step.get("error"), "approval": step.get("approval")}


def _run_view(run):
    return {"tenant": run["tenant"], "run_id": run["run_id"], "workflow_id": run["workflow_id"],
            "status": run["status"], "params": run.get("params") or {},
            "created_at": run.get("created_at"), "updated_at": run.get("updated_at"),
            "steps": [_step_view(run["steps"][sid]) for sid in run["step_order"]],
            "history_length": len(run.get("history") or [])}


def create_server(store, host="127.0.0.1", port=8080, scheduler=None):
    """Build (but do not start) a ThreadingHTTPServer bound to ``host:port``."""
    if scheduler is None:
        from .scheduler import Scheduler

        scheduler = Scheduler(store)
    return ThreadingHTTPServer((host, int(port)),
                               type("FlowdHandler", (_Handler,), {"scheduler": scheduler}))

