            "kind": step.get("kind", KIND_TASK),
            "depends_on": list(step["depends_on"]),
            "max_attempts": step["max_attempts"],
            "status": STEP_PENDING,
            "attempt": 0,
            "worker_id": None,
            "lease_deadline": None,
            "next_attempt_at": None,
            "ready_at": None,
            "started_at": None,
            "finished_at": None,
            "result": None,
            "error": None,
            "approval": None,
        }
        for step in plan["steps"]
    }
    return {
        "tenant": tenant,
        "workflow_id": workflow_id,
        "run_id": run_id,
        "status": RUN_PENDING,
        "params": params or {},
        "created_at": now_iso,
        "updated_at": now_iso,
        "step_order": list(plan["order"]),
        "order_index": {sid: i for i, sid in enumerate(plan["order"])},
        "steps": steps,
        "history": [],
    }

